// This reads the config for the handles and the window, and the watch list for
// the ids to skip. Both are read by name.
const cfg = $('Settings').first().json;
const seen = $('Read What We Already Saw').all().map((i) => i.json || {});

const handles = String(cfg.handles || '')
  .split(/[\s,]+/)
  .map((h) => h.trim().replace(/^@/, ''))
  .filter(Boolean);

if (!handles.length) {
  throw new Error('Put at least one X handle in Settings.');
}

const days = Number(cfg.days_back) || 7;
const end = new Date();
const start = new Date(Date.now() - days * 86400000);

function day(d) {
  return d.toISOString().slice(0, 10);
}

// Bright Data skips these during the crawl rather than returning them for us to
// throw away. The list is capped because it travels in the request body and a
// year of ids would eventually be the largest thing in it.
const skip = seen
  .map((r) => String(r.post_id || ''))
  .filter(Boolean)
  .slice(-Number(cfg.max_skip_ids || 200));

const payload = handles.map((h) => ({
  url: `https://x.com/${h}`,
  start_date: day(start),
  end_date: day(end),
  num_of_posts: Number(cfg.posts_per_account) || 25,
  posts_to_not_include: skip,
}));

return [{
  json: {
    payload,
    handles,
    window_days: days,
    skipping: skip.length,
  },
}];

// single-item input: one progress call, one response.
const status = $input.first().json || {};
const cfg = $('Settings').first().json;

const state = String(status.status || 'unknown');
// $runIndex is the number of previous runs of this node, so it is the poll
// count. Without a ceiling a stuck snapshot spins all night.
const polls = $runIndex + 1;
const giveUp = polls >= (Number(cfg.max_polls) || 20);

return [{
  json: {
    state,
    records: Number(status.records) || 0,
    polls,
    give_up: giveUp,
    done: state === 'ready' || state === 'failed' || giveUp,
  },
}];

const cfg = $('Settings').first().json;
const plan = $('Plan The Crawl').first().json || {};
const rows = $input.all().map((i) => i.json);

// Bright Data returns a failed input as a row inside the results array, and it
// can be the first one - so the shape of row zero is not the shape of the set.
const posts = [];
const errors = [];
for (const raw of rows.flat()) {
  if (!raw || typeof raw !== 'object') continue;
  if (raw.error || raw.error_code) {
    errors.push(String(raw.error || raw.error_code).slice(0, 160));
    continue;
  }
  const id = String(raw.id || '');
  const text = String(raw.description || '').trim();
  if (!id || !text) continue;

  // hashtags, photos and videos are null rather than [] when a post has none.
  const arr = (v) => (Array.isArray(v) ? v : []);
  const when = Date.parse(raw.date_posted || '');

  posts.push({
    post_id: id,
    handle: String(raw.user_posted || '').toLowerCase(),
    name: String(raw.name || ''),
    text,
    url: String(raw.url || ''),
    when: Number.isFinite(when) ? new Date(when).toISOString() : '',
    when_ms: Number.isFinite(when) ? when : 0,
    likes: Number(raw.likes) || 0,
    reposts: Number(raw.reposts) || 0,
    replies: Number(raw.replies) || 0,
    quotes: Number(raw.quotes) || 0,
    bookmarks: Number(raw.bookmarks) || 0,
    views: Number(raw.views) || 0,
    followers: Number(raw.followers) || 0,
    is_repost: raw.is_repost === true,
    hashtags: arr(raw.hashtags).map(String),
    has_media: arr(raw.photos).length > 0 || arr(raw.videos).length > 0,
    external_url: String(raw.external_url || ''),
  });
}

function engagement(p) {
  return p.likes + p.reposts * 2 + p.quotes * 2 + p.replies;
}

function median(list) {
  if (!list.length) return 0;
  const s = [...list].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

// The account is its own baseline. A repost is somebody else's post being
// amplified, so it does not belong in the median of what this account's own
// writing normally does.
const byHandle = new Map();
for (const p of posts) {
  const list = byHandle.get(p.handle) || [];
  list.push(p);
  byHandle.set(p.handle, list);
}

const baselines = {};
for (const [handle, list] of byHandle) {
  const own = list.filter((p) => !p.is_repost).map(engagement).filter((n) => n > 0);
  baselines[handle] = {
    median: median(own),
    posts: list.length,
    own_posts: own.length,
  };
}

// Rules tag the post; the model only writes prose about it. Keeping the tag in
// code means the same post is tagged the same way on every run.
const TAGS = [
  ['launch', /\b(launch(ed|ing)?|introducing|now available|general availability|\bGA\b|ship(ped|ping)|new (feature|product|release)|out now|v\d+(\.\d+)? is)\b/i],
  ['pricing', /\b(pricing|price|free tier|paid plan|per seat|discount|now free|cost(s)?\b|subscription)\b/i],
  ['funding', /\b(raised|funding|series [a-e]\b|seed round|valuation|acquired|acquisition|投资)\b/i],
  ['hiring', /\b(we('| a)re hiring|join our team|open role|now hiring|apply now|careers page)\b/i],
  ['incident', /\b(outage|downtime|degraded|incident|postmortem|status page|apolog(y|ise|ize)|we're aware)\b/i],
  ['event', /\b(webinar|conference|keynote|meetup|workshop|register now|live (at|from))\b/i],
];

function tagOf(text) {
  for (const [tag, re] of TAGS) if (re.test(text)) return tag;
  return 'general';
}

const minMultiple = Number(cfg.min_multiple) || 2;

const scored = posts.map((p) => {
  const base = baselines[p.handle] || { median: 0 };
  const eng = engagement(p);
  // A zero baseline means we have nothing to compare against yet - one post, or
  // an account whose every post scored zero. Those are reported as unrated
  // rather than silently treated as infinitely good.
  const multiple = base.median > 0 ? eng / base.median : null;
  const tag = tagOf(p.text);
  return {
    ...p,
    engagement: eng,
    baseline: base.median,
    multiple: multiple === null ? null : Math.round(multiple * 10) / 10,
    tag,
    // A launch or a price change is worth seeing even on a quiet day; anything
    // else has to earn its place by beating the account's own normal.
    notable:
      !p.is_repost &&
      (['launch', 'pricing', 'funding', 'incident'].includes(tag) ||
        (multiple !== null && multiple >= minMultiple)),
  };
});

scored.sort((a, b) => (b.multiple || 0) - (a.multiple || 0) || b.engagement - a.engagement);

const notable = scored.filter((p) => p.notable).slice(0, Number(cfg.max_in_digest) || 10);

return [{
  json: {
    notable,
    all_posts: scored,
    baselines,
    errors,
    crawled: posts.length,
    skipped_already_seen: plan.skipping || 0,
    window_days: plan.window_days || 0,
    brief: notable
      .map((p, i) => `${i + 1}. @${p.handle} [${p.tag}] ${p.text.replace(/\s+/g, ' ').slice(0, 240)}`)
      .join('\n'),
  },
}];

// single-item input: the scorer emits one object holding every post.
const scored = $('Score Against Their Own Normal').first().json || {};
const cfg = $('Settings').first().json;
const notable = Array.isArray(scored.notable) ? scored.notable : [];

let summaries = '';
try {
  summaries = String(($input.first().json || {}).text || '');
} catch (e) {
  summaries = '';
}

// Numbered lines only. A line that does not start with a number is dropped
// rather than attached to whichever post comes next.
const summaryFor = new Map();
for (const line of summaries.split('\n')) {
  const m = line.match(/^\s*(\d+)[.)]\s*(.+)$/);
  if (!m) continue;
  const idx = Number(m[1]) - 1;
  if (notable[idx]) summaryFor.set(notable[idx].post_id, m[2].trim());
}

function plural(n, one, many) {
  return `${n} ${n === 1 ? one : many}`;
}

const lines = [];
lines.push(`*What your competitors announced on X* - last ${plural(scored.window_days || 0, 'day', 'days')}`);
const baseText = Object.entries(scored.baselines || {})
  .map(([h, b]) => `@${h} normally ${Math.round(b.median)}`)
  .join(' | ');
lines.push(`${plural(scored.crawled || 0, 'post', 'posts')} crawled${scored.skipped_already_seen ? `, ${scored.skipped_already_seen} skipped as already seen` : ''}. Baselines: ${baseText || 'not enough history yet'}.`);
if ((scored.errors || []).length) {
  lines.push(`_${plural(scored.errors.length, 'account', 'accounts')} did not crawl: ${scored.errors.slice(0, 2).join('; ')}_`);
}
lines.push('');

if (!notable.length) {
  lines.push('Nothing cleared the bar. Everything posted was ordinary for the account that posted it.');
}

for (const p of notable) {
  const how =
    p.multiple === null
      ? 'no baseline yet'
      : `${p.multiple}x their normal`;
  lines.push(`*@${p.handle}* - ${p.tag}, ${how}`);
  const summary = summaryFor.get(p.post_id);
  if (summary) lines.push(`    ${summary}`);
  lines.push(`    ${p.likes} likes, ${p.reposts} reposts, ${p.replies} replies${p.views ? `, ${p.views} views` : ''}`);
  lines.push(`    ${p.url}`);
  lines.push('');
}

const rows = (scored.all_posts || []).map((p) => ({
  seen_on: new Date().toISOString().slice(0, 10),
  handle: p.handle,
  posted_at: p.when,
  tag: p.tag,
  notable: p.notable ? 'yes' : 'no',
  summary: summaryFor.get(p.post_id) || '',
  text: p.text.replace(/\s+/g, ' ').slice(0, 400),
  engagement: p.engagement,
  baseline: p.baseline,
  multiple: p.multiple === null ? '' : p.multiple,
  likes: p.likes,
  reposts: p.reposts,
  replies: p.replies,
  views: p.views,
  is_repost: p.is_repost ? 'yes' : 'no',
  url: p.url,
  post_id: p.post_id,
}));

// One item per row so the Sheets append writes one row per post rather than a
// single row whose columns are "message" and "rows".
return [{ json: { message: lines.join('\n'), rows, row_count: rows.length } }];

// Every crawled post id is written back, notable or not, so tomorrow's crawl
// can skip it at Bright Data's end. This hangs beside the report rather than
// behind it, because a Data Table write emits the row it stored.
const first = ($input.all()[0] || {}).json || {};
const rows = Array.isArray(first.rows) ? first.rows : [];
return rows.map((r) => ({
  json: { post_id: r.post_id, handle: r.handle, seen_on: r.seen_on },
}));
